CREATE TABLE IF NOT EXISTS people (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 public_id VARCHAR(20) UNIQUE,
 nombre VARCHAR(100) NOT NULL, apellido VARCHAR(100) NOT NULL,
 telefono VARCHAR(60) NOT NULL, phone_normalized VARCHAR(60) NOT NULL,
 dni VARCHAR(30) NOT NULL DEFAULT '', email VARCHAR(254) NOT NULL DEFAULT '',
 direccion TEXT NOT NULL, observaciones TEXT NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE,
 emergency_name TEXT NOT NULL, emergency_relationship TEXT NOT NULL,
 emergency_phone TEXT NOT NULL, emergency_notes TEXT NOT NULL,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX idx_people_name(apellido,nombre), INDEX idx_phone(phone_normalized), INDEX idx_dni(dni), INDEX idx_email(email)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS instructors (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activities (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL UNIQUE,instructor_id INT UNSIGNED NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(instructor_id) REFERENCES instructors(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_allowed_days (activity_id INT UNSIGNED NOT NULL,day TINYINT UNSIGNED NOT NULL,PRIMARY KEY(activity_id,day),FOREIGN KEY(activity_id) REFERENCES activities(id),CHECK(day BETWEEN 0 AND 6)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS periods (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,year SMALLINT NOT NULL,month TINYINT NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(year,month),CHECK(month BETWEEN 1 AND 12)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS enrollments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_id INT UNSIGNED NOT NULL,period_id INT UNSIGNED NOT NULL,activity_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(person_id,period_id,activity_id),FOREIGN KEY(person_id) REFERENCES people(id),FOREIGN KEY(period_id) REFERENCES periods(id),FOREIGN KEY(activity_id) REFERENCES activities(id),INDEX idx_enroll_period(period_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS enrollment_slots (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,enrollment_id INT UNSIGNED NOT NULL,day TINYINT UNSIGNED NOT NULL,start CHAR(5) NOT NULL,end CHAR(5) NOT NULL,FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE,UNIQUE(enrollment_id,day,start,end),CHECK(end > start),CHECK(day BETWEEN 0 AND 6)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS monthly_accounts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,person_id INT UNSIGNED NOT NULL,period_id INT UNSIGNED NOT NULL,amount_due DECIMAL(12,2) NULL,UNIQUE(person_id,period_id),FOREIGN KEY(person_id) REFERENCES people(id),FOREIGN KEY(period_id) REFERENCES periods(id),CHECK(amount_due >= 0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,account_id INT UNSIGNED NOT NULL,date DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,method ENUM('cash','transfer') NOT NULL,notes TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(account_id) REFERENCES monthly_accounts(id),CHECK(amount > 0),INDEX idx_payment_date(date)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS advertising_investments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,date DATE NOT NULL,concept VARCHAR(200) NOT NULL,amount DECIMAL(12,2) NOT NULL,notes TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CHECK(amount >= 0),INDEX idx_ad_date(date)) ENGINE=InnoDB;
